class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        ans = 0
        for l in range(n):
            mx, cost = 0, 0
            for r in range(l, n):
                if mx > nums[r]:
                    cost += mx - nums[r]
                else:
                    mx = nums[r]
                if cost > k:
                    break
                ans += 1
        return ans

