from collections import deque
class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        st = deque()
        cur = 0
        ans = 0
        l = 0
        for r, x in enumerate(nums):
            cnt = 1
            while st and st[-1][0] <= x:
                v, c = st.pop()
                cur += (v - x) * c
                cnt += c
            st.append([x, cnt])
            while cur > k:
                st[0][1] -= 1
                if st[0][1] == 0:
                    st.popleft()
                else:
                    cur -= st[0][0] - st[1][0]
                l += 1
            ans += r - l + 1
        return ans

