class Solution {
public:
    long long countNonDecreasingSubarrays(vector<int>& nums, int k) {
        deque<pair<long long,long long>> st;
        long long cur = 0, ans = 0;
        int l = 0;
        for (int r = 0; r < (int)nums.size(); r++) {
            long long x = nums[r], cnt = 1;
            while (!st.empty() && st.back().first <= x) {
                auto [v, c] = st.back(); st.pop_back();
                cur += (v - x) * c;
                cnt += c;
            }
            st.push_back({x, cnt});
            while (cur > k) {
                st.front().second--;
                if (st.front().second == 0) st.pop_front();
                else cur -= st.front().first - (++st.begin())->first;
                l++;
            }
            ans += r - l + 1;
        }
        return ans;
    }
};

