class Solution {
    public long countNonDecreasingSubarrays(int[] nums, int k) {
        LinkedList<long[]> st = new LinkedList<>();
        long cur = 0, ans = 0;
        int l = 0;
        for (int r = 0; r < nums.length; r++) {
            long x = nums[r], cnt = 1;
            while (!st.isEmpty() && st.peekLast()[0] <= x) {
                long[] b = st.pollLast();
                cur += (b[0] - x) * b[1];
                cnt += b[1];
            }
            st.addLast(new long[]{x, cnt});
            while (cur > k) {
                long[] f = st.peekFirst();
                f[1]--;
                if (f[1] == 0) st.pollFirst();
                else cur -= f[0] - st.get(1)[0];
                l++;
            }
            ans += r - l + 1;
        }
        return ans;
    }
}

